<div class="card"><div class="card-header"><h3 class="card-title">Parcelas para liquidação</h3></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Documento / Parcela</th><th>Fornecedor</th><th>Empenho</th><th>Parcela</th><th>Composição</th><th>Status</th></tr></thead><tbody><?php foreach($itens as $i):?><tr><td><a href="/documentos/<?=e($i['documento_id'])?>"><strong><?=e($i['tipo_documento'])?> <?=e($i['documento_numero'])?></strong></a><div class="small">Parcela <?=e($i['numero_parcela'])?></div></td><td><?=e($i['fornecedor'])?></td><td><?=e($i['empenho_numero'])?>/<?=e($i['empenho_ano'])?></td><td><?=money($i['valor_total'])?></td><td><?=money($i['soma_componentes'])?></td><td><span class="badge <?=$i['status']==='CONCLUIDA'?'text-bg-success':'text-bg-warning'?>"><?=e($i['status'])?></span><?php if($i['data_liquidacao']):?><div class="small"><?=e($i['data_liquidacao'])?></div><?php endif;?></td></tr><?php endforeach;?><?php if(!$itens):?><tr><td colspan="6" class="text-center text-body-secondary py-4">Fila vazia.</td></tr><?php endif;?></tbody></table></div></div>